#!/usr/bin/env bash
# Generated by `verdant-studio publish` from studio/src/Studio/Engine.lex.tex. Do not edit.
# REQ-ENGINE-TRACKING for the toolchain: a pin that waits on an upstream fix moves itself. When the latest
# release of LexLean or prism-code contains the commit its pin waits on, this proposes moving the pin to that
# release through propose-command, whose export and studio check test it before it merges.
set -euo pipefail
cd "$(git rev-parse --show-toplevel)"
contains() { case "$(gh api "repos/$1/compare/$2...$3" --jq .status || true)" in ahead|identical) return 0;; *) return 1;; esac; }
latest() { gh api "repos/$1/releases?per_page=30" --jq "[.[] | select(.prerelease | not) | select(.tag_name | startswith(\"$2\"))][0].tag_name // empty"; }
commit() { gh api "repos/$1/commits/$2" --jq .sha; }
moved=''
# LexLean waits on eacdb95c, UOR-Foundation/lexlean#639.
tag=$(latest UOR-Foundation/lexlean v)
if [ -n "$tag" ] && contains UOR-Foundation/lexlean eacdb95c4d997c36decedd1c4bc9bbea6600fadf "$tag"; then
  sha=$(commit UOR-Foundation/lexlean "$tag")
  if ! grep -q "$sha" .github/lexlean.pin; then
    echo "--git https://github.com/UOR-Foundation/lexlean --rev $sha" > .github/lexlean.pin
    moved="${moved:+$moved,} LexLean $tag ($sha)"
  fi
fi
# prism-code waits on 93f5640c, UOR-Foundation/prismpm#931.
tag=$(latest UOR-Foundation/prismpm prism-code-v)
if [ -n "$tag" ] && contains UOR-Foundation/prismpm 93f5640c6014c9a4700ec5f5c0069b3f6e50d444 "$tag"; then
  sha=$(commit UOR-Foundation/prismpm "$tag")
  ops=studio/src/Studio/Ops.lex.tex
  line=$(grep -n '^  name: prismCodeRev,' "$ops" | cut -d: -f1)
  if [ -n "$line" ] && ! sed -n "$((line + 3))p" "$ops" | grep -q "$sha"; then
    sed -i "$((line + 3))s|lit \"[0-9a-f]*\"|lit \"$sha\"|" "$ops"
    moved="${moved:+$moved,} prism-code $tag ($sha)"
  fi
fi
if [ -z "$moved" ]; then echo "no pin moves: no latest release contains the commit a pin waits on"; exit 0; fi
if gh api "repos/$GITHUB_REPOSITORY/pulls?state=open&per_page=100" --jq '.[].title' | grep -q '^verdant_studio propose-command: Move the toolchain pins'; then
  echo "a pin move is already proposed"; exit 0
fi
summary="Move the toolchain pins to the upstream releases that now contain the fixes they waited on:$moved. The propose-command export and the studio check test the move before it merges (REQ-ENGINE-TRACKING)"
gh workflow run operate.yml --repo "$GITHUB_REPOSITORY" --ref main -f args=propose-command -f input="$summary
$(git diff -- .github/lexlean.pin studio/src)"
echo "proposed:$moved"
